import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let q = conc.Mutex(0)
    let go = conc.Cond(q)
    scope {
        let w1 = task effect io {
            go.wait(|v| v > 0)
            io.println("w1")
        }
        let w2 = task effect io {
            go.wait(|v| v > 0)
            io.println("w2")
        }
        let s = task effect io {
            let _ = q.set(2)
            let _ = go.broadcast()
            io.println("set")
        }
        let _ = w1.await()
        let _ = w2.await()
        let _ = s.await()
    }
    return Ok(())
}
